import os
import openai

def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    target_lang = config.get("target_lang", "English")
    result = {
        key: client.chat.completions.create(
            model="gpt-4o",
            messages=[
                {"role": "system", "content": f"Translate the following text to {target_lang}."},
                {"role": "user", "content": str(value)}
            ],
            temperature=0
        ).choices[0].message.content.strip()
        for key, value in payload.items()
    }
    return result
